import React, { useState, useEffect } from 'react';
import api from '../../../lib/api';
import LoadingState from '../../../components/ui/LoadingState';

const CurriculumEditor = () => {
  const [catalog, setCatalog] = useState([]);
  const [selectedId, setSelectedId] = useState(null);
  const [detail, setDetail] = useState(null);
  const [jsonText, setJsonText] = useState('');
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [message, setMessage] = useState('');

  useEffect(() => {
    api.adminCurriculum().then((data) => {
      setCatalog(data.catalog || []);
      setLoading(false);
    });
  }, []);

  const selectModule = async (nodeId) => {
    setSelectedId(nodeId);
    setMessage('');
    const data = await api.adminCurriculumModule(nodeId);
    setDetail(data);
    const sections = data.customOverride?.sections || data.effective?.sections || [];
    setJsonText(JSON.stringify({ sections }, null, 2));
  };

  const save = async () => {
    if (!selectedId) return;
    setSaving(true);
    setMessage('');
    try {
      const parsed = JSON.parse(jsonText);
      await api.adminSaveCurriculum(selectedId, parsed);
      setMessage('Saved successfully');
      selectModule(selectedId);
    } catch (err) {
      setMessage(err.message || 'Save failed');
    } finally {
      setSaving(false);
    }
  };

  const reset = async () => {
    if (!selectedId || !window.confirm('Remove custom override and revert to catalog?')) return;
    await api.adminDeleteCurriculum(selectedId);
    setMessage('Reverted to catalog default');
    selectModule(selectedId);
  };

  if (loading) return <LoadingState message="Loading curriculum..." />;

  return (
    <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
      <div className="card p-4 max-h-[70vh] overflow-y-auto">
        <h3 className="font-semibold mb-3">Modules ({catalog.length})</h3>
        <ul className="space-y-1">
          {catalog.map((m) => (
            <li key={m.id}>
              <button
                onClick={() => selectModule(m.id)}
                className={`w-full text-left px-3 py-2 rounded text-sm ${
                  selectedId === m.id ? 'bg-primary-50 text-primary' : 'hover:bg-surface-50'
                }`}
              >
                {m.title}
                <span className="block text-xs text-text-secondary capitalize">{m.subject}</span>
              </button>
            </li>
          ))}
        </ul>
      </div>

      <div className="lg:col-span-2 card p-4">
        {selectedId ? (
          <>
            <div className="flex justify-between items-center mb-3">
              <h3 className="font-semibold">{detail?.meta?.title || selectedId}</h3>
              <div className="flex gap-2">
                <button onClick={reset} className="btn btn-outline px-3 py-1.5 text-sm">Revert</button>
                <button onClick={save} disabled={saving} className="btn btn-primary px-3 py-1.5 text-sm">
                  {saving ? 'Saving...' : 'Save Override'}
                </button>
              </div>
            </div>
            {message && <p className="text-sm mb-2 text-primary">{message}</p>}
            <p className="text-xs text-text-secondary mb-2">
              Edit lesson JSON. Saved overrides take precedence over static catalog for all users.
            </p>
            <textarea
              value={jsonText}
              onChange={(e) => setJsonText(e.target.value)}
              className="input w-full font-mono text-xs min-h-[400px]"
              spellCheck={false}
            />
          </>
        ) : (
          <p className="text-text-secondary text-center py-12">Select a module to edit</p>
        )}
      </div>
    </div>
  );
};

export default CurriculumEditor;
