import React, { useState, useEffect } from 'react';
import api from '../../../lib/api';
import LoadingState from '../../../components/ui/LoadingState';

const UsersPanel = () => {
  const [users, setUsers] = useState([]);
  const [loading, setLoading] = useState(true);

  const load = () => {
    setLoading(true);
    api.adminUsers().then(setUsers).finally(() => setLoading(false));
  };

  useEffect(() => { load(); }, []);

  const changeRole = async (userId, role) => {
    await api.adminSetRole(userId, role);
    load();
  };

  if (loading) return <LoadingState message="Loading users..." />;

  return (
    <div className="card overflow-hidden">
      <table className="w-full text-sm">
        <thead className="bg-surface-50 border-b border-border">
          <tr>
            <th className="text-left p-3">Name</th>
            <th className="text-left p-3">Email</th>
            <th className="text-left p-3">Role</th>
            <th className="text-left p-3">Joined</th>
          </tr>
        </thead>
        <tbody>
          {users.map((u) => (
            <tr key={u.id} className="border-b border-border-light">
              <td className="p-3">{u.name}</td>
              <td className="p-3 text-text-secondary">{u.email}</td>
              <td className="p-3">
                <select
                  value={u.role || 'student'}
                  onChange={(e) => changeRole(u.id, e.target.value)}
                  className="input text-sm py-1"
                >
                  <option value="student">Student</option>
                  <option value="instructor">Instructor</option>
                  <option value="admin">Admin</option>
                </select>
              </td>
              <td className="p-3 text-text-secondary text-xs">{u.createdAt?.split('T')[0]}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};

export default UsersPanel;
